formula:
var price = num( v.price );
var taxRate = num( v.tax );
var fees = num( v.fees );
var down = num( v.down );
var trade = num( v.trade );
var rate = num( v.rate );
var months = Math.max( num( v.term ), 1 );

/* Tax is charged on the vehicle before the deposit comes off, which is why a
   larger deposit does not reduce the tax bill. Most states also tax the price
   after the trade-in is deducted rather than before, so the trade comes off
   first and the deposit does not. */
var taxable = Math.max( price - trade, 0 );
var tax = taxable * taxRate / 100;
var financed = Math.max( price + tax + fees - down - trade, 0 );

if ( financed <= 0 ) {
	return { label: 'Monthly payment', value: '—', rows: [], note: 'Enter a price, or reduce the deposit below it.' };
}

var payment = monthlyPayment( financed, rate, months / 12 );
var total = payment * months;
var interest = Math.max( total - financed, 0 );

return {
	label: 'Monthly payment',
	value: money2( payment ),
	sub: 'for ' + decimals( months, 0 ) + ' months at ' + decimals( rate, 2 ) + '% APR',
	bar: [
		{ pct: share( financed, total ), color: ACCENT },
		{ pct: share( interest, total ), color: WARN }
	],
	rows: [
		{ label: 'Amount financed', value: money( financed ), color: ACCENT },
		{ label: 'Total interest', value: money( interest ), color: WARN, emphasis: interest > financed * 0.2 },
		{ label: 'Total of payments', value: money( total ) },
		{ label: 'Sales tax', value: money( tax ) },
		{ label: 'Total cost of the car', value: money( total + down + trade ), divide: true }
	],
	note: 'The total cost line adds your deposit and trade-in back in, because money you put down is money you spent on the car even though the loan never sees it.'
};
